CREATE TABLE ferramentas(id BIGSERIAL PRIMARY KEY,patrimonio VARCHAR(255) NOT NULL UNIQUE,nome VARCHAR(255) NOT NULL,categoria VARCHAR(255),marca VARCHAR(255),modelo VARCHAR(255),numero_serie VARCHAR(255),estado_conservacao VARCHAR(50),status VARCHAR(50),localizacao VARCHAR(255),galpao_id BIGINT REFERENCES galpoes(id),valor NUMERIC(19,2),created_at TIMESTAMP);CREATE TABLE ferramenta_emprestimos(id BIGSERIAL PRIMARY KEY,ferramenta_id BIGINT NOT NULL REFERENCES ferramentas(id),responsavel_nome VARCHAR(255),responsavel_cpf VARCHAR(255),obra VARCHAR(255),frente_servico VARCHAR(255),emprestado_em TIMESTAMP,devolucao_prevista TIMESTAMP,devolvido_em TIMESTAMP,estado_saida VARCHAR(50),estado_devolucao VARCHAR(50),status VARCHAR(50),observacoes VARCHAR(1000),comprovante_codigo VARCHAR(40) UNIQUE);CREATE INDEX idx_ferramentas_status ON ferramentas(status);CREATE INDEX idx_emprestimos_status_prazo ON ferramenta_emprestimos(status,devolucao_prevista);
